   321|  putBody?: string;
   322|  message: string;
   323|}> {
   324|  const managementToken = readEnv('SUPABASE_ACCESS_TOKEN');
   325|  if (!managementToken) {
   326|    return { ok: false, tokenPresent: false, projectRef: null, message: 'SUPABASE_ACCESS_TOKEN not configured in runtime.' };
   327|  }
   328|  const projectRefMatch = supabaseUrl.match(/https:\/\/([a-z0-9-]+)\.supabase\.co/);
   329|  const projectRef = projectRefMatch?.[1] ?? null;
   330|  if (!projectRef) {
   331|    return { ok: false, tokenPresent: true, projectRef, message: `Could not extract project ref from Supabase URL: ${supabaseUrl}` };
   332|  }
   333|  try {
   334|    const authUrl = `https://api.supabase.com/v1/projects/${projectRef}/config/auth`;
   335|
   336|    const getResp = await fetch(authUrl, { headers: { Authorization: `Bearer ${managementToken}`, Accept: 'application/json' } });
   337|    const getText = await getResp.text();
   338|    if (!getResp.ok) {
   339|      return { ok: false, tokenPresent: true, projectRef, getStatus: getResp.status, getError: getText.slice(0, 300), message: `GET auth config failed: HTTP ${getResp.status}` };
   340|    }
   341|    const getConfig = JSON.parse(getText) as { uri_allow_list?: string; site_url?: string; };
   342|    const rawAllowList = typeof getConfig.uri_allow_list === 'string' ? getConfig.uri_allow_list : '';
   343|    const redirectUrls = rawAllowList.split(/[\s,]+/).map((u) => u.trim()).filter(Boolean);
   344|    const beforeUrls = [...redirectUrls];
   345|
   346|    if (redirectUrls.includes(redirectTo)) {
   347|      return { ok: true, tokenPresent: true, projectRef, getResponse: getText.slice(0, 400), beforeUrls, afterUrls: beforeUrls, message: 'Redirect URL already allowed.' };
