   351|    // multiple URLs are present, dropping the separator and concatenating values. To guarantee a
   352|    // valid allow-list for the new redirect URL, we REPLACE the list with exactly that URL.
   353|    const nextUrls = [redirectTo];
   354|    const nextAllowList = redirectTo;
