    || lower.endsWith('.key')
    || lower.includes('/.env')
    || lower.includes('secret')
    || lower.includes('private-key');
  if (blocked && lower !== '.env.example') {
    throw new Error('Refusing to write likely secret-bearing repository paths.');
  }
  return repoPath;
}
