  return {
    provider: 'ivx-ai',
    action: 'ai_generate_fix',
    path: filePath || null,
    issue: issue.slice(0, 200),
    fixedCode,
    fixedCodeLength: fixedCode.length,
    model: result.providerMetadata.model,
    readOnly: true,
    secretValuesReturned: false,
    timestamp: nowIso(),
  };
}

